import struct
import math
import array
import sys
import os

class AudioData:
    def __init__(self, rate=48000, channels=1, bits=16, encoding="Signed Integer PCM", comments=None):
        self.rate = rate
        self.channels = channels
        self.bits = bits
        self.encoding = encoding
        self.comments = comments if comments is not None else []
        self.channels_data = [array.array('f') for _ in range(channels)]
        self.file_size = 0
        self.file_type = "wav"

    @property
    def num_frames(self):
        if not self.channels_data:
            return 0
        return len(self.channels_data[0])

    @property
    def duration(self):
        if self.rate <= 0:
            return 0.0
        return self.num_frames / float(self.rate)

    @property
    def precision(self):
        enc = self.encoding.lower()
        if "64-bit float" in enc or "54-bit" in enc or "text" in enc or "double" in enc:
            return 54
        if "float" in enc or "25-bit" in enc:
            return 25
        if "u-law" in enc or "mu-law" in enc:
            return 14
        if "a-law" in enc:
            return 13
        if "adpcm" in enc:
            return 14 if "ms" in enc else 13
        return self.bits if self.bits > 0 else 16

    @property
    def full_encoding_name(self):
        enc = self.encoding.lower()
        if "text" in enc:
            return "Floating Point (text) PCM"
        if "64-bit float" in enc:
            return "64-bit Floating Point PCM"
        if "float" in enc:
            return "32-bit Floating Point PCM"
        if "u-law" in enc or "mu-law" in enc:
            return "8-bit u-law"
        if "a-law" in enc:
            return "8-bit A-law"
        if "ms adpcm" in enc or "ms-adpcm" in enc:
            return "4-bit MS ADPCM"
        if "ima adpcm" in enc or "ima-adpcm" in enc:
            return "4-bit IMA ADPCM"
        if "unsigned" in enc:
            return f"{self.bits}-bit Unsigned Integer PCM"
        return f"{self.bits}-bit Signed Integer PCM"

    @property
    def short_encoding_name(self):
        enc = self.encoding.lower()
        if "text" in enc:
            return "Floating Point (text) PCM"
        if "float" in enc:
            return "Floating Point PCM"
        if "u-law" in enc or "mu-law" in enc:
            return "u-law"
        if "a-law" in enc:
            return "A-law"
        if "ms" in enc and "adpcm" in enc:
            return "MS ADPCM"
        if "ima" in enc and "adpcm" in enc:
            return "IMA ADPCM"
        if "unsigned" in enc:
            return "Unsigned Integer PCM"
        return "Signed Integer PCM"


def format_duration(seconds):
    h = int(seconds // 3600)
    m = int((seconds % 3600) // 60)
    s = seconds % 60
    return f"{h:02d}:{m:02d}:{s:05.2f}"


def format_size(num_bytes):
    if num_bytes == 0:
        return "0"
    if num_bytes < 1000:
        return str(num_bytes)
    if num_bytes < 1000000:
        k = num_bytes / 1000.0
        if k < 10.0:
            return f"{k:.2f}k"
        elif k < 100.0:
            return f"{k:.1f}k"
        else:
            return f"{int(round(k))}k"
    m = num_bytes / 1000000.0
    if m < 10.0:
        return f"{m:.2f}M"
    elif m < 100.0:
        return f"{m:.1f}M"
    else:
        return f"{int(round(m))}M"


def format_bitrate(bits_per_sec):
    if bits_per_sec == 0:
        return "0"
    if bits_per_sec < 1000:
        return str(int(round(bits_per_sec)))
    if bits_per_sec < 1000000:
        k = bits_per_sec / 1000.0
        if k < 10.0:
            return f"{k:.2f}k"
        elif k < 100.0:
            return f"{k:.1f}k"
        else:
            return f"{int(round(k))}k"
    m = bits_per_sec / 1000000.0
    if m < 10.0:
        return f"{m:.2f}M"
    elif m < 100.0:
        return f"{m:.1f}M"
    else:
        return f"{int(round(m))}M"

