def load_audio(filename, file_type=None, rate=None, channels=None, bits=None, encoding=None, volume=1.0):
    if filename == "-n" or filename == "null":
        audio = AudioData(rate=rate or 48000, channels=channels or 1, bits=bits or 32, encoding=encoding or "Signed Integer PCM")
        audio.file_type = "null"
        audio.file_size = 0
        return audio

    if filename == "-":
        raw_data = sys.stdin.buffer.read()
        fsize = len(raw_data)
    else:
        if not os.path.exists(filename):
            raise FileNotFoundError(f"can't open input file `{filename}': No such file or directory")
        fsize = os.path.getsize(filename)
        with open(filename, "rb") as f:
            raw_data = f.read()

    ext = file_type or (filename.split(".")[-1].lower() if "." in filename else "wav")
    audio = AudioData()
    audio.file_size = fsize
    audio.file_type = ext

    if ext == "dat":
        _parse_dat(raw_data, audio)
    elif ext in ("au", "snd"):
        _parse_au(raw_data, audio)
    elif ext in ("aiff", "aif", "aifc"):
        _parse_aiff(raw_data, audio)
    elif ext in ("raw", "pcm", "s16", "u8", "f32"):
        _parse_raw(raw_data, audio, rate or 48000, channels or 1, bits or 16, encoding or "Signed Integer PCM")
    else:
        # Default WAV / RIFF
        _parse_wav(raw_data, audio, rate, channels, bits, encoding)

    if volume != 1.0:
        for ch in range(audio.channels):
            for i in range(len(audio.channels_data[ch])):
                audio.channels_data[ch][i] *= volume

    return audio


def save_audio(audio, filename, file_type=None, bits=None, encoding=None, rate=None, channels=None, comments=None):
    if filename == "-n" or filename == "null":
        return

    ext = file_type or (filename.split(".")[-1].lower() if "." in filename else "wav")

    out_rate = rate or audio.rate
    out_channels = channels or audio.channels
    out_bits = bits or audio.bits
    out_encoding = encoding or audio.encoding

    # Convert rate/channels if necessary
    data = audio.channels_data
    if out_channels != audio.channels:
        data = _resample_channels(data, audio.channels, out_channels)

    if out_rate != audio.rate:
        data = _resample_rate(data, audio.rate, out_rate)

    comments = comments or audio.comments or ["Processed by SoX"]

    if ext == "dat":
        content = _write_dat(data, out_rate, out_channels)
    elif ext in ("au", "snd"):
        content = _write_au(data, out_rate, out_channels, out_bits, out_encoding, comments)
    elif ext in ("aiff", "aif", "aifc"):
        content = _write_aiff(data, out_rate, out_channels, out_bits, out_encoding, comments)
    elif ext in ("raw", "pcm", "s16", "u8", "f32"):
        content = _write_raw(data, out_bits, out_encoding)
    else:
        content = _write_wav(data, out_rate, out_channels, out_bits, out_encoding, comments)

    if filename == "-":
        sys.stdout.buffer.write(content)
    else:
        with open(filename, "wb") as f:
            f.write(content)


def _parse_wav(data, audio, override_rate=None, override_channels=None, override_bits=None, override_encoding=None):
    if len(data) < 12 or data[:4] != b"RIFF" or data[8:12] != b"WAVE":
        raise ValueError("Not a valid WAV file")

    idx = 12
    fmt_found = False
    audio_format = 1
    channels = 1
    rate = 48000
    bits = 16
    pcm_bytes = b""

    while idx < len(data) - 8:
        chunk_id = data[idx:idx+4]
        chunk_size = struct.unpack("<I", data[idx+4:idx+8])[0]
        idx += 8
        if chunk_id == b"fmt " and chunk_size >= 16:
            audio_format, channels, rate, _, _, bits = struct.unpack("<HHIIHH", data[idx:idx+16])
            fmt_found = True
        elif chunk_id == b"data":
            pcm_bytes = data[idx:idx+chunk_size]
        idx += chunk_size
        if chunk_size % 2 == 1:
            idx += 1

    audio.rate = override_rate or rate
    audio.channels = override_channels or channels
    audio.bits = override_bits or bits

    if audio_format == 1:
        audio.encoding = "Unsigned Integer PCM" if bits == 8 else "Signed Integer PCM"
    elif audio_format == 3:
        audio.encoding = "Floating Point PCM"
    elif audio_format == 6:
        audio.encoding = "8-bit A-law"
        audio.bits = 8
    elif audio_format == 7:
        audio.encoding = "8-bit u-law"
        audio.bits = 8
    else:
        audio.encoding = "Signed Integer PCM"

    if override_encoding:
        audio.encoding = override_encoding

    _decode_pcm(pcm_bytes, audio)


def _write_wav(channels_data, rate, channels, bits, encoding, comments=None):
    num_frames = len(channels_data[0]) if channels_data else 0
    pcm_bytes, audio_format, bits_per_sample = _encode_pcm(channels_data, bits, encoding)

    block_align = channels * (bits_per_sample // 8)
    byte_rate = rate * block_align
    fmt_chunk = struct.pack("<HHIIHH", audio_format, channels, rate, byte_rate, block_align, bits_per_sample)

    header = b"RIFF" + struct.pack("<I", 36 + len(pcm_bytes)) + b"WAVE"
    header += b"fmt " + struct.pack("<I", 16) + fmt_chunk
    header += b"data" + struct.pack("<I", len(pcm_bytes)) + pcm_bytes
    return header


def _parse_au(data, audio):
    if len(data) < 24 or data[:4] != b".snd":
        raise ValueError("Not a valid AU file")

    hdr_size, data_size, encoding_code, rate, channels = struct.unpack(">IIIII", data[4:24])
    audio.rate = rate
    audio.channels = channels

    if encoding_code == 1:
        audio.encoding = "8-bit u-law"
        audio.bits = 8
    elif encoding_code == 2:
        audio.encoding = "Signed Integer PCM"
        audio.bits = 8
    elif encoding_code == 3:
        audio.encoding = "Signed Integer PCM"
        audio.bits = 16
    elif encoding_code == 4:
        audio.encoding = "Signed Integer PCM"
        audio.bits = 24
    elif encoding_code == 5:
        audio.encoding = "Signed Integer PCM"
        audio.bits = 32
    elif encoding_code == 6:
        audio.encoding = "Floating Point PCM"
        audio.bits = 32
    elif encoding_code == 7:
        audio.encoding = "Floating Point PCM"
        audio.bits = 64
    elif encoding_code == 27:
        audio.encoding = "8-bit A-law"
        audio.bits = 8
    else:
        audio.encoding = "Signed Integer PCM"
        audio.bits = 16

    pcm_bytes = data[hdr_size:]
    _decode_pcm(pcm_bytes, audio, big_endian=True)


def _write_au(channels_data, rate, channels, bits, encoding, comments=None):
    num_frames = len(channels_data[0]) if channels_data else 0
    pcm_bytes, _, bits_per_sample = _encode_pcm(channels_data, bits, encoding, big_endian=True)

    enc_code = 3 # 16-bit PCM
    if "u-law" in encoding.lower() or "mu-law" in encoding.lower():
        enc_code = 1
    elif "a-law" in encoding.lower():
        enc_code = 27
    elif "float" in encoding.lower():
        enc_code = 6 if bits_per_sample == 32 else 7
    elif bits_per_sample == 8:
        enc_code = 2
    elif bits_per_sample == 24:
        enc_code = 4
    elif bits_per_sample == 32:
        enc_code = 5

    comment_bytes = b"Processed by SoX\x00"
    hdr_size = 24 + len(comment_bytes)
    # Pad hdr_size to 8 byte boundary
    if hdr_size % 8 != 0:
        comment_bytes += b"\x00" * (8 - (hdr_size % 8))
        hdr_size = 24 + len(comment_bytes)

    header = struct.pack(">4sIIIII", b".snd", hdr_size, len(pcm_bytes), enc_code, rate, channels) + comment_bytes
    return header + pcm_bytes


def _parse_aiff(data, audio):
    if len(data) < 12 or data[:4] != b"FORM" or data[8:12] not in (b"AIFF", b"AIFC"):
        raise ValueError("Not a valid AIFF file")

    idx = 12
    channels = 1
    rate = 48000
    bits = 16
    pcm_bytes = b""

    while idx < len(data) - 8:
        chunk_id = data[idx:idx+4]
        chunk_size = struct.unpack(">I", data[idx+4:idx+8])[0]
        idx += 8
        if chunk_id == b"COMM" and chunk_size >= 18:
            num_channels, num_frames, sample_size = struct.unpack(">hIh", data[idx:idx+8])
            # IEEE 80-bit float sample rate
            exponent, mantissa = struct.unpack(">HQ", data[idx+8:idx+18])
