                audio.channels_data[c].append(val / 8388608.0)
    elif bits == 32:
        fmt = f"{'>' if big_endian else '<'}i"
        num_frames = (len(pcm_bytes) // 4) // ch
        idx = 0
        for _ in range(num_frames):
