def _resample_channels(channels_data, in_ch, out_ch):
    if in_ch == out_ch:
        return channels_data
    num_frames = len(channels_data[0]) if channels_data else 0
    new_data = [array.array('f') for _ in range(out_ch)]

    if in_ch == 1 and out_ch >= 2:
        for c in range(out_ch):
            new_data[c] = array.array('f', channels_data[0])
    elif in_ch >= 2 and out_ch == 1:
        mix = array.array('f')
        for i in range(num_frames):
            s = sum(channels_data[c][i] for c in range(in_ch)) / float(in_ch)
            mix.append(s)
        new_data[0] = mix
    else:
        for c in range(out_ch):
            src_c = c % in_ch
            new_data[c] = array.array('f', channels_data[src_c])

    return new_data


def _resample_rate(channels_data, in_rate, out_rate):
    if in_rate == out_rate or in_rate <= 0 or out_rate <= 0:
        return channels_data
    num_frames = len(channels_data[0]) if channels_data else 0
    out_frames = int(round(num_frames * out_rate / float(in_rate)))
    new_data = [array.array('f') for _ in range(len(channels_data))]

    ratio = float(in_rate) / float(out_rate)
    for c in range(len(channels_data)):
        ch_arr = channels_data[c]
        out_arr = new_data[c]
        for i in range(out_frames):
            src_pos = i * ratio
            i0 = int(src_pos)
            if i0 >= num_frames - 1:
                out_arr.append(ch_arr[-1] if ch_arr else 0.0)
            else:
                frac = src_pos - i0
                out_arr.append(ch_arr[i0] * (1.0 - frac) + ch_arr[i0 + 1] * frac)

    return new_data

