def effect_stats(audio, args):
    all_samples = []
    for i in range(audio.num_frames):
        for ch in range(audio.channels):
            all_samples.append(audio.channels_data[ch][i])

    min_lev = min(all_samples) if all_samples else 0.0
    max_lev = max(all_samples) if all_samples else 0.0
    dc_offset = sum(all_samples) / max(1, len(all_samples)) if all_samples else 0.0

