import sys
import os
from src.audio import load_audio, format_duration, format_size, format_bitrate

SOXI_HELP = """Usage: soxi [-V[level]] [-T] [-t|-r|-c|-s|-d|-D|-b|-B|-p|-e|-a] infile1 ...

-V[n]\tIncrement or set verbosity level (default is 2)
-T\tWith -s, -d or -D, display the total across all given files

-t\tShow detected file-type
-r\tShow sample-rate
-c\tShow number of channels
-s\tShow number of samples (0 if unavailable)
-d\tShow duration in hours, minutes and seconds (0 if unavailable)
-D\tShow duration in seconds (0 if unavailable)
-b\tShow number of bits per sample (0 if not applicable)
-B\tShow the bitrate averaged over the whole file (0 if unavailable)
-p\tShow estimated sample precision in bits
-e\tShow the name of the audio encoding
-a\tShow file comments (annotations) if available

With no options, as much information as is available is shown for
each given file."""

def run_soxi(prog_name, args):
    if not args or "--help" in args or "-h" in args:
        print(f"{prog_name}:      SoX v14.4.2\n")
        print(SOXI_HELP)
        sys.exit(0)

    verbosity = 2
    show_total = False
    query_mode = None
    input_files = []

    # Format options preceding input file
    fmt_type = None
    fmt_rate = None
    fmt_channels = None
    fmt_bits = None
    fmt_encoding = None

    idx = 0
    while idx < len(args):
        arg = args[idx]
        if arg == "-T":
            show_total = True
        elif arg in ("-t", "-r", "-c", "-s", "-d", "-D", "-b", "-B", "-p", "-e", "-a"):
            query_mode = arg[1]
        elif arg.startswith("-V"):
            if len(arg) > 2:
                try:
                    verbosity = int(arg[2:])
                except ValueError:
                    verbosity = 3
            else:
                verbosity = 3
        elif arg in ("--version", "-version"):
            print(f"{prog_name}:      SoX v14.4.2")
            sys.exit(0)
        elif arg.startswith("-"):
            # Unknown option
            pass
        else:
            input_files.append(arg)
        idx += 1

    if not input_files:
        print(f"{prog_name}:      SoX v14.4.2\n")
        print(SOXI_HELP)
        sys.exit(0)

    total_samples = 0
    total_duration = 0.0
    exit_code = 0

    audios = []
    for fname in input_files:
        try:
            audio = load_audio(fname, file_type=fmt_type, rate=fmt_rate, channels=fmt_channels, bits=fmt_bits, encoding=fmt_encoding)
            audios.append((fname, audio))
            total_samples += audio.num_frames
            total_duration += audio.duration
        except Exception as e:
            sys.stderr.write(f"{prog_name} FAIL formats: {e}\n")
            exit_code = 1

    if not audios:
        sys.exit(exit_code)

    if query_mode is None:
        # Full summary mode
        for i, (fname, audio) in enumerate(audios):
            dur_str = format_duration(audio.duration)
            s_str = str(audio.num_frames)

            if audio.rate == 44100:
                sec_val = audio.num_frames / 588.0
                if audio.num_frames % 588 == 0 or sec_val == int(sec_val):
                    cdda_str = f"= {int(round(sec_val))} CDDA sectors"
                else:
                    cdda_str = f"= {sec_val:.1f} CDDA sectors"
            else:
                sec_val = round(audio.duration * 75.0, 2)
                if sec_val == int(sec_val):
                    cdda_str = f"~ {int(sec_val)} CDDA sectors"
                else:
                    cdda_str = f"~ {sec_val} CDDA sectors"

            fsize_str = format_size(audio.file_size)
            bitrate_val = (audio.file_size * 8.0 / audio.duration) if audio.duration > 0 else (audio.rate * audio.channels * audio.bits)
            bitrate_str = format_bitrate(bitrate_val)

            print(f"\nInput File     : '{fname}'")
            print(f"Channels       : {audio.channels}")
            print(f"Sample Rate    : {audio.rate}")
            print(f"Precision      : {audio.precision}-bit")
            if audio.file_type == "dat":
                print(f"Sample Encoding: Floating Point (text) PCM\n")
            else:
                print(f"Duration       : {dur_str} = {s_str} samples {cdda_str}")
                print(f"File Size      : {fsize_str}")
                print(f"Bit Rate       : {bitrate_str}")
                print(f"Sample Encoding: {audio.full_encoding_name}")

                if audio.comments:
                    for c in audio.comments:
                        print(f"Comment        : '{c}'")

                if verbosity >= 3:
                    print(f"Endian Type    : little")
                    print(f"Reverse Nibbles: no")
                    print(f"Reverse Bits   : no")
                print()

        if len(input_files) > 1:
            tot_dur_str = format_duration(total_duration)
            print(f"Total Duration of {len(input_files)} files: {tot_dur_str}")

    else:
        # Query flag mode
        if show_total and query_mode in ("s", "d", "D"):
            if query_mode == "s":
                print(f"{float(total_samples):.6f}")
            elif query_mode == "d":
                print(format_duration(total_duration))
            elif query_mode == "D":
                print(f"{total_duration:.6f}")
        else:
            for fname, audio in audios:
                if query_mode == "t":
                    print(audio.file_type)
                elif query_mode == "r":
                    print(audio.rate)
                elif query_mode == "c":
                    print(audio.channels)
                elif query_mode == "s":
                    print(audio.num_frames)
                elif query_mode == "d":
                    print(format_duration(audio.duration))
                elif query_mode == "D":
                    print(f"{audio.duration:.6f}")
                elif query_mode == "b":
                    print(audio.bits if audio.file_type != "dat" else 0)
                elif query_mode == "B":
                    bitrate_val = (audio.file_size * 8.0 / audio.duration) if audio.duration > 0 else (audio.rate * audio.channels * audio.bits)
                    print(format_bitrate(bitrate_val))
                elif query_mode == "p":
                    print(audio.precision)
                elif query_mode == "e":
                    print(audio.short_encoding_name)
                elif query_mode == "a":
                    print("\n".join(audio.comments))

    sys.exit(exit_code)

